import java.util.*;

public class Main {
    static int constrainedSubsetSum(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        dp[0] = nums[0];
        int best = dp[0];

        for (int i = 1; i < n; i++) {
            int bestPrev = 0;
            for (int j = Math.max(0, i - k); j < i; j++) {
                bestPrev = Math.max(bestPrev, dp[j]);
            }
            dp[i] = nums[i] + Math.max(0, bestPrev);
            best = Math.max(best, dp[i]);
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(constrainedSubsetSum(new int[]{10, 2, -10, 5, 20}, 2));
        System.out.println(constrainedSubsetSum(new int[]{-1, -2, -3}, 1));
    }
}

