        int bestPrev = dq.empty() ? 0 : max(0, dp[dq.front()]);
        dp[i] = nums[i] + bestPrev;
        best = max(best, dp[i]);
        while (!dq.empty() && dp[dq.back()] <= dp[i]) dq.pop_back();
        dq.push_back(i);
